import{_ as a,o as i,c as t,ag as l}from"./chunks/framework.DNmTgtHf.js";const p=JSON.parse('{"title":"Availability vs Reliability vs Fault Tolerance","description":"","frontmatter":{},"headers":[],"relativePath":"system_design/availability/AvailabilityReliabilityFaultTolerance.md","filePath":"system_design/availability/AvailabilityReliabilityFaultTolerance.md"}'),s={name:"system_design/availability/AvailabilityReliabilityFaultTolerance.md"};function r(o,e,n,h,c,d){return i(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="availability-vs-reliability-vs-fault-tolerance" tabindex="-1">Availability vs Reliability vs Fault Tolerance <a class="header-anchor" href="#availability-vs-reliability-vs-fault-tolerance" aria-label="Permalink to &quot;Availability vs Reliability vs Fault Tolerance&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="the-three-definitions" tabindex="-1">The three definitions <a class="header-anchor" href="#the-three-definitions" aria-label="Permalink to &quot;The three definitions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Concept</th><th>Question it answers</th><th>Property of</th></tr></thead><tbody><tr><td><strong>Reliability</strong></td><td>How often does a component fail?</td><td>The component itself</td></tr><tr><td><strong>Availability</strong></td><td>Can users use the service <em>right now</em>?</td><td>The service</td></tr><tr><td><strong>Fault tolerance</strong></td><td>Can the system keep operating <em>while</em> failures occur?</td><td>The system design</td></tr></tbody></table><p><strong>Reliability</strong> — frequency/probability of failure; how long a component runs before breaking. A server that runs 5 years without crashing is highly reliable. <em>Reliable = breaks rarely.</em></p><p><strong>Availability</strong> — whether the system can continue serving traffic: the website responds, users can send messages, customers can place orders. <em>Available = users can use it.</em></p><p><strong>Fault tolerance</strong> — designed so that when a failure occurs, the system keeps working and users don&#39;t notice.</p><h3 id="reliability-helps-availability" tabindex="-1">Reliability helps availability <a class="header-anchor" href="#reliability-helps-availability" aria-label="Permalink to &quot;Reliability helps availability&quot;">​</a></h3><p>Fewer failures → less downtime → higher availability. That&#39;s why reliability <em>contributes</em> to availability.</p><h3 id="availability-does-not-require-reliability" tabindex="-1">Availability does NOT require reliability <a class="header-anchor" href="#availability-does-not-require-reliability" aria-label="Permalink to &quot;Availability does NOT require reliability&quot;">​</a></h3><p>A system can be highly available even if components fail frequently. 100 app servers with 1 crashing every hour sounds unreliable — but if the load balancer removes failed servers and traffic shifts, users never notice:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Component reliability = low</span></span>
<span class="line"><span>System availability  = high</span></span></code></pre></div><p>This is one of the most important distributed-systems concepts.</p><h3 id="reliability-does-not-guarantee-availability" tabindex="-1">Reliability does NOT guarantee availability <a class="header-anchor" href="#reliability-does-not-guarantee-availability" aria-label="Permalink to &quot;Reliability does NOT guarantee availability&quot;">​</a></h3><p>A single database server that crashes only once every 3 years is highly reliable — but when it crashes, the entire application stops for hours:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reliability  = high</span></span>
<span class="line"><span>Availability = low</span></span></code></pre></div><h3 id="fault-tolerance-availability-in-the-presence-of-failures" tabindex="-1">Fault tolerance = availability in the presence of failures <a class="header-anchor" href="#fault-tolerance-availability-in-the-presence-of-failures" aria-label="Permalink to &quot;Fault tolerance = availability in the presence of failures&quot;">​</a></h3><p>Availability asks &quot;can users use the system?&quot; Fault tolerance asks &quot;can users still use it <em>while things are failing</em>?&quot;</p><h2 id="high-availability-vs-fault-tolerance" tabindex="-1">High Availability vs Fault Tolerance <a class="header-anchor" href="#high-availability-vs-fault-tolerance" aria-label="Permalink to &quot;High Availability vs Fault Tolerance&quot;">​</a></h2><p><strong>High Availability (HA)</strong> — goal: very little downtime. Primary DB fails → replica promoted in ~30 seconds. Users may see a short outage, a few failed requests, a brief interruption.</p><p><strong>Fault Tolerance (FT)</strong> — goal: near-zero <em>visible</em> interruption. Primary fails → replica takes over immediately; users keep working, no noticeable downtime.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HA:  failure → small interruption → recovery</span></span>
<span class="line"><span>FT:  failure → service continues  → users don&#39;t notice</span></span></code></pre></div><h2 id="practical-examples" tabindex="-1">Practical examples <a class="header-anchor" href="#practical-examples" aria-label="Permalink to &quot;Practical examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setup</th><th>Reliability</th><th>Availability</th><th>Fault tolerance</th><th>Why</th></tr></thead><tbody><tr><td>1 app server, crashes once per 5 yrs</td><td>High</td><td>Low</td><td>None</td><td>When the server dies, the entire service dies</td></tr><tr><td>LB + 100 servers, failures common</td><td>Average per server</td><td>Very high</td><td>Moderate</td><td>Traffic shifts automatically; users continue</td></tr><tr><td>Primary + replica DB, promote on failure</td><td>Depends</td><td>High</td><td>Partial</td><td>Brief interruption still exists during promotion</td></tr><tr><td>Multi-node cluster, one node fails</td><td>Not necessarily perfect</td><td>Extremely high</td><td>High</td><td>Designed assuming failures will happen</td></tr></tbody></table><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><strong>&quot;If a system is reliable, is it automatically highly available?&quot;</strong> No — a single DB server failing once every 3 years is reliable, but its one failure takes the whole application down for hours.</li><li><strong>&quot;If a system is highly available, is it automatically reliable?&quot;</strong> No — 100 servers with one crashing every hour are individually unreliable, yet the load balancer keeps the service available.</li><li><strong>&quot;Availability and reliability are the same thing.&quot;</strong> Reliability measures failures (component focus); availability measures whether users can use the service (service-continuity focus).</li><li><strong>&quot;Fault tolerance means failures never happen.&quot;</strong> Failures absolutely happen — fault tolerance means the system continues operating <em>despite</em> them.</li><li><strong>&quot;If there&#39;s even a tiny interruption, is it still fault tolerant?&quot;</strong> Nuance: in theory FT aims for no visible interruption; in practice perfect zero impact is extremely difficult — a few failed requests, millisecond-level disruption, or tiny switchover delays may remain. The goal is making failures <em>effectively invisible</em> to users.</li><li><strong>Understanding check (correct):</strong> HA = system works again after a short interruption; FT = system continues without users noticing.</li></ol><h2 id="performance-characteristics" tabindex="-1">Performance characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance characteristics&quot;">​</a></h2><h3 id="how-availability-is-increased" tabindex="-1">How availability is increased <a class="header-anchor" href="#how-availability-is-increased" aria-label="Permalink to &quot;How availability is increased&quot;">​</a></h3><p>Through <strong>redundancy</strong>: multiple servers, multiple replicas, multiple nodes, automatic failover, load balancing.</p><p>Key insight: modern distributed systems <strong>assume hardware failures will happen</strong>. The goal is not preventing all failures — it&#39;s <em>surviving</em> them.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><h3 id="hospital-analogy" tabindex="-1">Hospital analogy <a class="header-anchor" href="#hospital-analogy" aria-label="Permalink to &quot;Hospital analogy&quot;">​</a></h3><ul><li><strong>Hospital A:</strong> 1 doctor who never takes leave — doctor reliability high, hospital availability low (doctor sick → hospital closes).</li><li><strong>Hospital B:</strong> 50 doctors, some always sick or on leave — individual reliability lower, hospital availability very high (always open).</li></ul><p>That&#39;s exactly how distributed systems use redundancy.</p><h3 id="netflix-style-thinking" tabindex="-1">Netflix-style thinking <a class="header-anchor" href="#netflix-style-thinking" aria-label="Permalink to &quot;Netflix-style thinking&quot;">​</a></h3><p>Large distributed systems expect servers, disks, and networks to fail. Design philosophy: <strong>failures are inevitable; downtime is optional.</strong> The system stays available because failures are isolated and traffic is redirected.</p><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. What does reliability measure?</strong> A. How often a component fails.</p><p><strong>Q. What does availability measure?</strong> A. Whether users can use the service right now.</p><p><strong>Q. Does high reliability guarantee high availability?</strong> A. No — a single highly reliable server still creates downtime when it eventually fails.</p><p><strong>Q. Does high availability guarantee high reliability?</strong> A. No — components may fail frequently while redundancy keeps the service running.</p><p><strong>Q. High availability vs fault tolerance?</strong> A. HA allows small interruptions; FT aims for no noticeable interruption.</p><p><strong>Q. What is the core distributed-systems mindset?</strong> A. Assume failures will happen and design the system to continue operating.</p>`,43)])])}const b=a(s,[["render",r]]);export{p as __pageData,b as default};
